function runningMaximum(nums) {
  const out = [];
  for (let i = 0; i < nums.length; i++) {
    let best = nums[0];
    for (let j = 0; j <= i; j++) {
      if (nums[j] > best) best = nums[j];
    }
    out.push(best);
  }
  return out;
}

