function countValidSplits(nums) {
  let count = 0;
  for (let i = 0; i <= nums.length - 2; i++) {
    let left = 0;
    for (let j = 0; j <= i; j++) left += nums[j];
    let right = 0;
    for (let j = i + 1; j < nums.length; j++) right += nums[j];
    if (left >= right) count += 1;
  }
  return count;
}

code.python:
def count_valid_splits(nums):
    count = 0
    n = len(nums)
    for i in range(n - 1):
        left = 0
        for j in range(i + 1):
            left += nums[j]
        right = 0
        for j in range(i + 1, n):
            right += nums[j]
        if left >= right:
            count += 1
    return count

